class Solution:
    def isSubstringPresent(self, s: str) -> bool:
        n = len(s)
        if n < 2:
            return False

        # Generate all substrings of length 2 in s
        substrings = set()
        for i in range(n - 1):
            substrings.add(s[i:i+2])

        # Generate the reverse of s
        reversed_s = s[::-1]

        # Check if any substring from s exists in reversed_s as a substring
        for sub in substrings:
            if sub in reversed_s:
                return True

        return False
```

