from typing import List

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return 1  # Any single element >= 0 works

        min_len = n + 1

        # Check all subarrays
        for i in range(n):
            for j in range(i, n):
                # Compute OR of nums[i:j+1]
                or_val = 0
                for x in nums[i:j+1]:
                    or_val |= x
                if or_val >= k:
                    min_len = min(min_len, j - i + 1)

        return min_len if min_len <= n else -1
