            top_left_options = [
                (r - 1, c - 1),
                (r - 1, c),
                (r, c - 1),
                (r, c)
            ]

            for tr, tc in top_left_options:
                if tr < 0 or tc < 0:
                    continue

                # Collect the four cells of this 2x2 square
                cells = []
                for i in range(tr, tr + 2):
                    for j in range(tc, tc + 2):
                        cells.append(grid[i][j])

                # Count occurrences of target_color and other color
                target_count = cells.count(target_color)
                other_count = cells.count('B') if target_color == 'W' else cells.count('W')

                # If we change one cell to target_color, we need at least 3 of target_color already
                if target_count >= 3:
                    return True
                if other_count == 1 and target_count == 3:
                    # Already 3 of target, 1 other -> change that 1 to target
                    return True
                # If we can change the one different cell to target_color
