                # If we have 2 of target and 2 of other, changing one might not help unless we aim for the other color
                if target_count == 2 and other_count == 2:
                    # Check if changing one of the 'other' cells to target makes it 3-1 -> not enough yet
                    # But if we aim for the other color, we already have 2 of it, need 3
                    # So this case doesn't help directly unless we pick the right target_color
                    pass

                # Try the other color as target
                other_color = 'B' if target_color == 'W' else 'W'
                if can_make_square_by_changing(r, c, other_color):
                    return True

                return False

        # Iterate over every cell that could be changed
        for r in range(rows):
            for c in range(cols):
                # Try changing this cell to 'B'
                if can_make_square_by_changing(r, c, 'B'):
                    return True
                # Try changing this cell to 'W'
                if can_make_square_by_changing(r, c, 'W'):
