class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        # Map each character to its index in s and in t
        index_in_s = {char: i for i, char in enumerate(s)}
        index_in_t = {char: i for i, char in enumerate(t)}

        total_diff = 0
        for char in s:
            total_diff += abs(index_in_s[char] - index_in_t[char])

        return total_diff
```

