        # Determine if a subarray starting at i of length k is strictly increasing
        def is_increasing(i: int) -> bool:
            for j in range(i, i + k - 1):
                if nums[j + 1] <= nums[j]:
                    return False
            return True

        # Check every possible start index for the first subarray
        for a in range(n - k + 1):
            if is_increasing(a):
                # The second subarray must start exactly k positions later
                b = a + k
                if b + k - 1 < n and is_increasing(b):
                    return True
        return False
