class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        res = list(s)
        n = len(res)

        for i in range(n):
            if k < 0:
                break

            current = ord(res[i]) - ord('a')
            target = 0  # we want 'a'

            # Calculate the minimal distance to change res[i] to 'a'
            diff = (current - target + 26) % 26

            if diff <= k:
                res[i] = 'a'
                k -= diff

        return "".join(res)
