class Solution:
    def minAnagramLength(self, s: str) -> int:
        from collections import Counter
        n = len(s)

        # Try all possible lengths from 1 to n
        for length in range(1, n + 1):
            if n % length != 0:
                continue

            block_len = length
            # Count total occurrences of each character in s
            total_counts = Counter(s)

            # Each block (subsegment) must be an anagram of t,
            # so each character count in each block must be total_counts[char] / block_len
            # and must be an integer.

            possible = True
            for i in range(0, n, block_len):
                block = s[i:i + block_len]
                block_counts = Counter(block)

                for ch, count in block_counts.items():
                    if total_counts[ch] % block_len != 0:
                        possible = False
                        break
                    if block_counts[ch] != total_counts[ch] // block_len:
                        possible = False
                        break
                if not possible:
                    break

            if possible:
                return length

        return n
