class Solution:
    def valueAfterKSeconds(self, n: int, k: int) -> int:
        MOD = 10**9 + 7

        # The value of a[n-1] after k seconds is given by the binomial coefficient:
        # C(n + k - 1, k)
        # We compute this using modular arithmetic.

        def nCr_mod(n, r):
            if r < 0 or r > n:
                return 0
            if r == 0 or r == n:
                return 1
            if r > n // 2:
                r = n - r

            # Compute numerator: n * (n-1) * ... * (n-r+1)
            num = 1
            for i in range(r):
                num = (num * (n - i)) % MOD

            # Compute denominator: r!
            den = 1
            for i in range(2, r + 1):
                den = (den * i) % MOD

            # Modular inverse using Fermat's little theorem (MOD is prime)
            den_inv = pow(den, MOD - 2, MOD)
            return (num * den_inv) % MOD

        return nCr_mod(n + k - 1, k)
```

