class Solution:
    def validStrings(self, n: int) -> List[str]:
        if n == 0:
            return []

        # Base cases for small n
        if n == 1:
            return ["0", "1"]
        if n == 2:
            return ["01", "10", "11"]  # "00" is invalid because "00" has no '1'

        result = []

        def backtrack(current: str):
            if len(current) == n:
                result.append(current)
                return

            # Try appending '0'
            if len(current) >= 1 and current[-1] == '0':
                # Cannot append '0' after '0' because "00" is invalid
                pass
            else:
                backtrack(current + "0")

            # Try appending '1'
            backtrack(current + "1")

        backtrack("")
        return result
