class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][j] = maximum length of a good subsequence ending at index i with exactly j changes
        # To save space, we can use a 2D array where dp[i][j] is the max length ending at i with j changes
        # However, since we need to consider subsequences (not necessarily contiguous), we can reframe:
        # Let dp[j] = maximum length of a good subsequence using exactly j changes, ending anywhere so far.
        # But we also need to know the last element to extend properly.
