            # Option: start new sequence at i
            dp[i][0] = max(dp[i][0], 1)

            # Try extending from previous indices
            for j in range(k + 1):
                # Case 1: nums[i] == nums[p] -> same number of changes
                if nums[i] == nums[i-1]:
                    if dp[i-1][j] != INF:
                        dp[i][j] = max(dp[i][j], dp[i-1][j] + 1)
                else:
                    # nums[i] != nums[i-1] -> would require one more change
                    if j > 0 and dp[i-1][j-1] != INF:
                        dp[i][j] = max(dp[i][j], dp[i-1][j-1] + 1)

            # But note: the above only considers extending from immediate previous index.
            # However, for subsequences, we can skip indices. So we need to consider all p < i.
            # But that would be O(n^2 * k). Given constraints (n<=500, k<=25), 500*500*25 = 6.25e6, acceptable.

            # Let's redo with considering all previous indices for correctness.

        # Reset and do full DP over all previous indices
        for i in range(n):
            for j in range(k + 1):
                dp[i][j] = 1  # at least the element itself

        for i in range(1, n):
            for j in range(k + 1):
                # Option 1: start new sequence at i
                if j == 0:
                    dp[i][j] = max(dp[i][j], 1)

                # Option 2: extend from some p < i
                for p in range(i):
                    if j == 0:
                        # Must have same value to have 0 changes
                        if nums[p] == nums[i]:
                            dp[i][j] = max(dp[i][j], dp[p][j] + 1)
                    else:
