class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            # Cannot perform any operation; only possible if already all 1s
            return 0 if all(x == 1 for x in nums) else -1

        ops = 0
        i = 0
        while i < n - 2:
            if nums[i] == 0:
                # Must flip a window starting at i to turn nums[i] into 1
                # Try flipping [i, i+1, i+2]
                nums[i], nums[i+1], nums[i+2] = 1 - nums[i], 1 - nums[i+1], 1 - nums[i+2]
                ops += 1
                i += 1
            else:
                i += 1

        # After the loop, check the last two elements
        if nums[n-1] == 0:
            return -1
        if nums[n-2] == 0:
            return -1

        # Check if all are 1 (already ensured by loop logic, but safe guard)
        return ops
