        def reduce_val(x: int, max_div: int, max_sub: int) -> int:
            # Try all possible numbers of divisions (0 to max_div)
            # and for each, decide optimally whether to subtract k.
            best = x

            # Compute how many times we can subtract k if we don't divide
            if x >= k:
                sub_count = (x - 1) // k  # max full subtractions possible
                if sub_count <= max_sub:
                    reduced = x - sub_count * k
