    # Each subset can be represented by a bitmask from 0 to (2^N - 1).
    # If the j-th bit is set, key j+1 is real.

    total_combinations = 1 << N
    valid_count = 0

    for mask in range(total_combinations):
        # Check if this combination satisfies all tests
        contradiction = False

        for C, keys, R in tests:
            # Count how many real keys are in this test set for the current mask
            real_count = 0
            for key in keys:
                # key is 1-indexed, so check bit (key-1)
                if (mask >> (key - 1)) & 1:
                    real_count += 1

            if R == 'o':
                # Door opened: need at least K real keys
                if real_count < K:
                    contradiction = True
                    break
            elif R == 'x':
                # Door did not open: need strictly less than K real keys
                if real_count >= K:
                    contradiction = True
                    break

        if not contradiction:
            valid_count += 1

